# State

The State element provides persistent state management across animation frames.

## Access

```tsx
const draw = (K: KlintContext) => {
  // Access the State element
  K.State.set("frameCount", K.frame);
  const lastFrame = K.State.get("frameCount");
}
```

## Methods

### set(key, value, callback?)

```ts
set(key: string, value: any, callback?: (key: string, value: any) => void) => void
```

Stores a value with an optional callback.

```tsx
// Basic usage
K.State.set("score", 100);

// With callback
K.State.set("playerPosition", { x: 200, y: 300 }, (key, value) => {
  console.log(`Updated ${key}:`, value);
});
```

### get(key, callback?)

```ts
get(key: string, callback?: (key: string, value: any) => void) => any
```

Retrieves a stored value with optional callback.

```tsx
const position = K.State.get("playerPosition");

// With callback
const score = K.State.get("score", (key, value) => {
  if (value > 1000) console.log("High score!");
});
```

### has(key)

```ts
has(key: string) => boolean
```

Checks if a key exists in state.

```tsx
if (!K.State.has("gameStarted")) {
  K.State.set("gameStarted", true);
  K.State.set("startTime", K.time);
}
```

### delete(key, callback?)

```ts
delete(key: string, callback?: (key: string) => void) => void
```

Removes a key from state with optional callback.

```tsx
K.State.delete("tempData");

// With callback
K.State.delete("oldScore", (key) => {
  console.log(`Removed ${key}`);
});
```

### log()

```ts
log() => Map<string, any>
```

Returns the entire state Map for debugging.

```tsx
console.log("Current state:", K.State.log());
```

## Common Patterns

### Initialization

```tsx
const draw = (K: KlintContext) => {
  // Initialize state on first frame
  if (!K.State.has("initialized")) {
    K.State.set("initialized", true);
    K.State.set("particles", []);
    K.State.set("score", 0);
    K.State.set("gameMode", "menu");
  }

  // Use state
  const gameMode = K.State.get("gameMode");
  if (gameMode === "menu") {
    drawMenu(K);
  } else if (gameMode === "playing") {
    drawGame(K);
  }
}
```

### Persistent Animation Data

```tsx
const draw = (K: KlintContext) => {
  // Initialize particles
  if (!K.State.has("particles")) {
    const particles = [];
    for (let i = 0; i < 50; i++) {
      particles.push({
        x: Math.random() * K.width,
        y: Math.random() * K.height,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        life: 1
      });
    }
    K.State.set("particles", particles);
  }

  // Update particles
  const particles = K.State.get("particles");
  particles.forEach(particle => {
    particle.x += particle.vx;
    particle.y += particle.vy;
    particle.life -= 0.01;

    // Respawn dead particles
    if (particle.life <= 0) {
      particle.x = Math.random() * K.width;
      particle.y = Math.random() * K.height;
      particle.life = 1;
    }
  });

  // Draw particles
  K.background("#111");
  particles.forEach(particle => {
    K.fillColor(`rgba(255, 255, 255, ${particle.life})`);
    K.circle(particle.x, particle.y, 3);
  });
}
```

### Game State Management

```tsx
const draw = (K: KlintContext) => {
  const { mouse, onClick } = KlintMouse();

  // Initialize game state
  if (!K.State.has("gameState")) {
    K.State.set("gameState", {
      mode: "menu",
      score: 0,
      level: 1,
      lives: 3,
      enemies: [],
      powerups: []
    });
  }

  const game = K.State.get("gameState");

  // Handle click events
  onClick(() => {
    if (game.mode === "menu") {
      game.mode = "playing";
      game.startTime = K.time;
    } else if (game.mode === "gameOver") {
      // Reset game
      game.mode = "menu";
      game.score = 0;
      game.level = 1;
      game.lives = 3;
    }
  });

  // Game logic based on mode
  switch (game.mode) {
    case "menu":
      drawMenu(K, game);
      break;
    case "playing":
      updateGame(K, game);
      drawGame(K, game);
      break;
    case "gameOver":
      drawGameOver(K, game);
      break;
  }
}

function updateGame(K, game) {
  // Spawn enemies
  if (!K.State.has("lastEnemySpawn")) {
    K.State.set("lastEnemySpawn", K.time);
  }

  if (K.time - K.State.get("lastEnemySpawn") > 2) {
    game.enemies.push({
      x: K.width,
      y: Math.random() * K.height,
      speed: 2 + game.level * 0.5
    });
    K.State.set("lastEnemySpawn", K.time);
  }

  // Update enemies
  game.enemies = game.enemies.filter(enemy => {
    enemy.x -= enemy.speed;
    return enemy.x > -50;
  });

  // Check for level progression
  if (game.score > game.level * 100) {
    game.level++;
  }
}
```

### State with Validation

```tsx
const draw = (K: KlintContext) => {
  // Initialize with validation
  if (!K.State.has("settings")) {
    const defaultSettings = {
      volume: 0.5,
      difficulty: "normal",
      showFPS: false
    };

    K.State.set("settings", defaultSettings, (key, value) => {
      // Validate settings
      if (value.volume < 0 || value.volume > 1) {
        console.warn("Volume must be between 0 and 1");
        value.volume = Math.max(0, Math.min(1, value.volume));
      }

      if (!["easy", "normal", "hard"].includes(value.difficulty)) {
        console.warn("Invalid difficulty, resetting to normal");
        value.difficulty = "normal";
      }
    });
  }

  // Use settings
  const settings = K.State.get("settings");

  // Show FPS if enabled
  if (settings.showFPS) {
    K.fillColor("white");
    K.textSize(16);
    K.text(`FPS: ${Math.round(1000 / K.deltaTime)}`, 20, 30);
  }
}
```

### Undo/Redo System

```tsx
const draw = (K: KlintContext) => {
  const { mouse, onClick } = KlintMouse();

  // Initialize history
  if (!K.State.has("history")) {
    K.State.set("history", {
      states: [{ points: [] }],
      currentIndex: 0
    });
  }

  const history = K.State.get("history");
  const currentState = history.states[history.currentIndex];

  // Add point on click
  onClick(() => {
    const newState = {
      points: [...currentState.points, { x: mouse.x, y: mouse.y }]
    };

    // Remove any states after current index (for branching)
    history.states = history.states.slice(0, history.currentIndex + 1);

    // Add new state
    history.states.push(newState);
    history.currentIndex++;

    // Limit history size
    if (history.states.length > 50) {
      history.states.shift();
      history.currentIndex--;
    }
  });

  // Undo/Redo with keyboard (simplified)
  // In real app, you'd use proper key event handling

  K.background("#222");

  // Draw all points
  currentState.points.forEach((point, i) => {
    K.fillColor(`hsl(${i * 10}, 70%, 60%)`);
    K.circle(point.x, point.y, 10);
  });

  // UI
  K.fillColor("white");
  K.textSize(14);
  K.text(`Points: ${currentState.points.length}`, 20, 30);
  K.text(`History: ${history.currentIndex}/${history.states.length - 1}`, 20, 50);
}
```

## Notes

- State persists across all animation frames until manually deleted
- Use State for data that needs to survive between draw calls
- State is instance-specific - different Klint components have separate state
- Perfect for game state, animation data, user preferences
- State callbacks are useful for validation and logging
- Consider using meaningful key names to avoid conflicts
- For complex state, consider storing objects rather than individual values
- State is kept in memory - large datasets should be managed carefully

docs.4-elements/Text:
# Text

The Text element provides advanced text layout, measurement, and typography features for complex text rendering.

## Access

```tsx
const draw = (K: KlintContext) => {
  // Access the Text element
  const size = K.Text.findTextSize("Hello World", 300);
  const letters = K.Text.splitTo("Text", "letters");
}
```

## Measurement Functions

### getTextMetrics(text)

```ts
getTextMetrics(text: string) => { width: number, height: number, baseline: number }
```

Returns detailed metrics for text rendering.

```tsx
const metrics = K.Text.getTextMetrics("Hello World")
console.log(metrics.width)    // Text width in pixels
console.log(metrics.height)   // Text height in pixels  
console.log(metrics.baseline) // Baseline offset
```

### textBounds(text)

```ts
textBounds(text: string) => { x: number, y: number, width: number, height: number }
```

Returns the bounding box for text rendering.

```tsx
const bounds = K.Text.textBounds("Sample Text")
K.strokeColor("red")
K.strokeWidth(1)
K.rectangle(bounds.x, bounds.y, bounds.width, bounds.height)
```

### findTextSize(text, distance, estimate?, direction?)

```ts
findTextSize(text: string, dist: number, estimate?: number, direction?: "x" | "y") => number
```

Finds the optimal text size to fit within specified dimensions using binary search.

```tsx
// Find size to fit text in 300px width
const size = K.Text.findTextSize("Long text string", 300, 50, "x")
K.textSize(size)
K.text("Long text string", 100, 200)

// Find size to fit text in 100px height
const vSize = K.Text.findTextSize("Tall Text", 100, 72, "y")
K.textSize(vSize)
K.text("Tall Text", 200, 200)
```

## Text Layout Functions

### splitTo(text, kind, options?)

```ts
splitTo(
  text: string, 
  kind: "letters" | "words" | "lines" | "all",
  options?: {
    maxWidth?: number,
    lineSpacing?: number,
    letterSpacing?: number,
    wordSpacing?: number
  }
) => Array<{
  char: string,
  x: number,
  y: number,
  metrics: { width: number, height: number, baseline: number },
  letterIndex?: number,
  wordIndex?: number,
  lineIndex?: number
}>
```

Splits text into individual components with positioning data for advanced layout.

```tsx
// Split into letters for animation
const letters = K.Text.splitTo("ANIMATE", "letters")
letters.forEach((letter, i) => {
  const offset = Math.sin(K.time * 0.005 + i * 0.5) * 20
  K.fillColor(`hsl(${i * 40}, 70%, 60%)`)
  K.text(letter.char, letter.x, letter.y + offset)
})

// Split into words with spacing
const words = K.Text.splitTo("Split these words", "words", {
  wordSpacing: 20
})
words.forEach((letter, i) => {
  if (letter.char !== " ") {
    K.fillColor("white")
    K.text(letter.char, letter.x + 100, letter.y + 300)
  }
})

// Multi-line text with custom spacing
const lines = K.Text.splitTo("Line one\nLine two\nLine three", "lines", {
  lineSpacing: 30
})
lines.forEach((letter) => {
  K.fillColor("cyan")
  K.text(letter.char, letter.x + 200, letter.y + 400)
})

// Get all metadata for complex layouts
const allData = K.Text.splitTo("Complex layout", "all")
allData.forEach((letter) => {
  const hue = (letter.letterIndex || 0) * 20
  K.fillColor(`hsl(${hue}, 60%, 70%)`)
  K.text(letter.char, letter.x + 300, letter.y + 500)
})
```

### circularText(text, radius?, fill?, offset?, arc?)

```ts
circularText(
  text: string,
  radius?: number,
  fill?: "fill" | "kerned" | "words",
  offset?: number,
  arc?: number
) => void
```

Renders text along a circular path with different layout modes.

```tsx
// Basic circular text
K.Text.circularText("CIRCULAR TEXT", 100)

// Kerned (proper character spacing)
K.Text.circularText("BETTER SPACING", 150, "kerned", Math.PI/4)

// Words distributed evenly
K.Text.circularText("WORD BASED LAYOUT", 200, "words", 0, Math.PI)

// Partial circle with offset
K.Text.circularText("PARTIAL ARC", 120, "fill", K.time * 0.01, Math.PI * 1.5)
```

## Animation Examples

### Letter-by-Letter Animation

```tsx
const draw = (K: KlintContext) => {
  K.background("#222")

  const text = "STAGGERED REVEAL"
  const letters = K.Text.splitTo(text, "letters")

  K.textSize(48)
  K.textAlign("center", "middle")

  letters.forEach((letter, i) => {
    // Staggered fade-in
    const delay = i * 0.1
    const progress = Math.max(0, (K.time * 0.003 - delay) % 2)
    const alpha = K.Easing.out(Math.min(1, progress))

    if (letter.char !== " ") {
      K.fillColor(`rgba(255, 255, 255, ${alpha})`)

      // Add bounce effect
      const bounce = Math.sin(progress * Math.PI) * 10
      K.text(letter.char, letter.x + K.width/2, letter.y + K.height/2 - bounce)
    }
  })
}
```

### Word Wave Effect

```tsx
const draw = (K: KlintContext) => {
  K.background("#111")

  const sentence = "WAVES OF TEXT"
  const letters = K.Text.splitTo(sentence, "all", { wordSpacing: 40 })

  K.textSize(32)
  K.textAlign("center", "middle")

  letters.forEach((letter) => {
    if (letter.char !== " ") {
      const wordOffset = (letter.wordIndex || 0) * 0.8
      const letterOffset = (letter.letterIndex || 0) * 0.2
      const wave = Math.sin(K.time * 0.004 + wordOffset + letterOffset) * 30

      const hue = ((letter.wordIndex || 0) * 60) % 360
      K.fillColor(`hsl(${hue}, 80%, 70%)`)

      K.text(letter.char, letter.x + K.width/2, letter.y + K.height/2 + wave)
    }
  })
}
```

### Responsive Text Sizing

```tsx
const draw = (K: KlintContext) => {
  K.background("#333")

  // Text that always fits the canvas width
  const availableWidth = K.width - 100
  const dynamicText = "RESPONSIVE TEXT SIZING"

  const optimalSize = K.Text.findTextSize(dynamicText, availableWidth, 72, "x")
  K.textSize(optimalSize)
  K.textAlign("center", "middle")
  K.fillColor("yellow")
  K.text(dynamicText, K.width/2, K.height/2)

  // Show bounds for debugging
  const bounds = K.Text.textBounds(dynamicText)
  K.strokeColor("red")
  K.strokeWidth(2)
  K.rectangle(
    K.width/2 + bounds.x, 
    K.height/2 + bounds.y, 
    bounds.width, 
    bounds.height
  )
}
```

### Circular Text Animation

```tsx
const draw = (K: KlintContext) => {
  K.background("#000")

  K.push()
  K.translate(K.width/2, K.height/2)

  // Animated circular text
  K.textSize(24)
  K.fillColor("cyan")

  // Rotating text with changing radius
  const radius = 100 + Math.sin(K.time * 0.002) * 30
  const offset = K.time * 0.005

  K.Text.circularText("SPINNING AROUND", radius, "kerned", offset)

  // Multiple rings
  K.fillColor("magenta")
  K.Text.circularText("INNER RING", 60, "fill", -offset * 1.5, Math.PI)

  K.fillColor("yellow")
  K.Text.circularText("OUTER SPACE", 180, "words", offset * 0.7, Math.PI * 1.8)

  K.pop()
}
```

### Multi-line Layout

```tsx
const draw = (K: KlintContext) => {
  K.background("#444")

  const poem = `Typography is the craft
of endowing human language
with a durable visual form`

  const lines = K.Text.splitTo(poem, "lines", {
    lineSpacing: 20
  })

  K.textSize(28)
  K.textAlign("center", "top")

  lines.forEach((letter, i) => {
    // Color-code each line
    const lineColor = letter.lineIndex === 0 ? "lightblue" :
                     letter.lineIndex === 1 ? "lightgreen" : "lightcoral"

    // Add typewriter effect
    const lineProgress = (K.time * 0.002 - (letter.lineIndex || 0) * 1.5) % 4
    const charIndex = letter.letterIndex || 0
    const shouldShow = charIndex < lineProgress * 20

    if (shouldShow) {
      K.fillColor(lineColor)
      K.text(letter.char, letter.x + K.width/2, letter.y + 200)
    }
  })
}
```

## Layout Options

The `splitTo` function accepts these options:

- **maxWidth**: Maximum line width for automatic wrapping
- **lineSpacing**: Additional space between lines (pixels)
- **letterSpacing**: Additional space between letters (pixels)  
- **wordSpacing**: Additional space between words (pixels)

## CircularText Fill Modes

- **"fill"**: Evenly distributes characters around the circle
- **"kerned"**: Uses actual character widths for natural spacing
- **"words"**: Distributes words evenly, maintaining word integrity

## Best Practices

- Use `findTextSize()` for responsive text that must fit specific dimensions
- Leverage `splitTo()` for character-level animations and effects
- Use `textBounds()` for precise positioning and collision detection
- `circularText()` with "kerned" mode provides the most natural appearance
- Combine with `K.Time` and `K.Easing` for smooth text animations
- Cache `splitTo()` results when text doesn't change to improve performance

## Notes

- All positioning respects current `textAlign` and `textBaseline` settings
- Text metrics include actual character dimensions, not just CSS font metrics
- `findTextSize()` uses binary search for efficient size calculation (max 16 iterations)
- Circular text automatically handles rotation and positioning
- Letter spacing and word spacing are additive to default browser spacing
- Performance scales with text length - consider caching for static text

docs.4-elements/Thing:
# Thing

The Thing element provides utility functions for debugging and development purposes.

## Access

```tsx
const draw = (K: KlintContext) => {
  // Access the Thing element
  K.Thing.log();
}
```

## Methods

### log()

```ts
log() => void
```

Logs the current Klint context to the browser console for debugging purposes.

```tsx
const draw = (K: KlintContext) => {
  // Log the context for debugging
  K.Thing.log();

  // Continue with drawing operations
  K.background("#333");
  K.circle(100, 100, 50);
}
```

## Use Cases

The Thing element is primarily intended for:

- **Development debugging**: Inspect the current state of the Klint context
- **Performance analysis**: Check internal properties and state
- **Learning**: Understand the structure of the Klint context object

## Example Usage

```tsx
const draw = (K: KlintContext) => {
  K.background("#222");

  // Debug context when clicking
  const { onClick } = KlintMouse();
  onClick(() => {
    console.log("=== Klint Context Debug ===");
    K.Thing.log();
  });

  K.fillColor("white");
  K.textAlign("center", "middle");
  K.text("Click to debug context", K.width/2, K.height/2);
}
```

## Notes

- The `log()` function outputs the entire Klint context object
- Useful during development to understand internal state
- Should typically be removed from production code
- The logged object contains all Klint properties, methods, and internal state

docs.4-elements/Time:
# Time

The Time element provides advanced timeline management and animation sequencing capabilities for complex animations.

## Access

```tsx
const draw = (K: KlintContext) => {
  // Access the Time element
  K.Time.timeline("main").use(K.time * 0.001).for(5);
  const progress = K.Time.progress();
}
```

## Core Methods

### timeline(key)

```ts
timeline(key: string) => Time
```

Creates or switches to a named timeline. Each timeline maintains its own progress and duration.

```tsx
// Create and switch to "intro" timeline
K.Time.timeline("intro")

// Create multiple timelines
K.Time.timeline("main")
K.Time.timeline("outro")
K.Time.timeline("background")
```

### use(progress)

```ts
use(progress: number) => Time
```

Sets the progress for the current timeline. Progress is automatically wrapped based on duration.

```tsx
// Use global time as progress
K.Time.timeline("main").use(K.time * 0.001)

// Use frame-based progress
K.Time.timeline("loop").use(K.frame * 0.02)

// Manual progress control
K.Time.timeline("custom").use(someProgressValue)
```

### for(duration)

```ts
for(duration: number) => Time
```

Sets the duration for the current timeline. This affects how progress wrapping works.

```tsx
// 5-second timeline
K.Time.timeline("main").for(5)

// 120-frame timeline
K.Time.timeline("frameBasedAnim").for(120)

// Infinite timeline (no wrapping)
K.Time.timeline("infinite").for(0)
```

### progress()

```ts
progress() => number
```

Returns the current progress (0-1) of the active timeline.

```tsx
const p = K.Time.timeline("main").progress()

// Use progress for animation
const rotation = p * Math.PI * 2
K.rotate(rotation)
```

## Advanced Methods

### stagger(num, offset?, callback?)

```ts
stagger(num: number, offset?: number, callback?: (progress: number, id: number, num: number) => void) => Time | Array<{id: number, progress: number}>
```

Creates staggered animations with delayed timing for multiple elements.

```tsx
// With callback - immediate execution
K.Time.timeline("stagger").use(K.time * 0.001).for(3)
K.Time.stagger(10, 0.1, (progress, id, num) => {
  const x = 50 + id * 80
  const y = 200 + progress * 200

  K.fillColor(`hsl(${id * 36}, 70%, 60%)`)
  K.circle(x, y, 20 + progress * 10)
})

// Without callback - returns array for manual iteration
K.Time.timeline("delayed").use(K.time * 0.0005).for(4)
const staggers = K.Time.stagger(8, 0.2)
staggers.forEach((stagger, i) => {
  const scale = 0.5 + stagger.progress * 1.5
  K.push()
  K.translate(100 + i * 60, 300)
  K.scale(scale)
  K.fillColor("cyan")
  K.rectangle(-15, -15, 30, 30)
  K.pop()
})
```

### between(from?, to?, callback)

```ts
between(from?: number, to?: number, callback: (progress: number) => void) => Time
```

Executes callback only when timeline progress is between specified range, with normalized progress.

```tsx
K.Time.timeline("sequence").use(K.time * 0.0008).for(6)

// First third of timeline (0-2 seconds)
K.Time.between(0, 0.33, (p) => {
  K.fillColor(`rgba(255, 0, 0, ${p})`)
  K.circle(200, 200, 50 + p * 50)
})

// Middle third (2-4 seconds)  
K.Time.between(0.33, 0.66, (p) => {
  K.fillColor("blue")
  K.rectangle(100 + p * 200, 300, 50, 50)
})

// Final third (4-6 seconds)
K.Time.between(0.66, 1, (p) => {
  const eased = K.Easing.bounceOut(p)
  K.fillColor("green")
  K.circle(400, 100 + eased * 100, 30)
})
```

## Animation Patterns

### Sequential Animation

```tsx
const draw = (K: KlintContext) => {
  K.background("#222")

  // 8-second sequence
  K.Time.timeline("sequence").use(K.time * 0.001).for(8)

  // Phase 1: Fade in (0-2s)
  K.Time.between(0, 0.25, (p) => {
    K.opacity(p)
    K.fillColor("white")
    K.textAlign("center", "middle")
    K.textSize(48)
    K.text("Hello", K.width/2, K.height/2)
  })

  // Phase 2: Scale up (2-4s)
  K.Time.between(0.25, 0.5, (p) => {
    const scale = 1 + p * 0.5
    K.push()
    K.translate(K.width/2, K.height/2)
    K.scale(scale)
    K.fillColor("yellow")
    K.textAlign("center", "middle")
    K.textSize(48)
    K.text("World", 0, 0)
    K.pop()
  })

  // Phase 3: Rotate (4-6s)
  K.Time.between(0.5, 0.75, (p) => {
    const rotation = p * Math.PI * 2
    K.push()
    K.translate(K.width/2, K.height/2)
    K.rotate(rotation)
    K.fillColor("cyan")
    K.rectangle(-50, -25, 100, 50)
    K.pop()
  })

  // Phase 4: Fade out (6-8s)
  K.Time.between(0.75, 1, (p) => {
    K.opacity(1 - p)
    K.fillColor("red")
    K.circle(K.width/2, K.height/2, 100)
  })
}
```

### Parallel Timelines

```tsx
const draw = (K: KlintContext) => {
  K.background("#111")

  // Background animation (slow, 10 seconds)
  K.Time.timeline("background").use(K.time * 0.0001).for(10)
  const bgProgress = K.Time.progress()
  K.fillColor(`hsl(${bgProgress * 360}, 30%, 15%)`)
  K.rectangle(0, 0, K.width, K.height)

  // Main content (fast, 2 seconds)  
  K.Time.timeline("main").use(K.time * 0.001).for(2)
  const mainProgress = K.Time.progress()
  K.fillColor("white")
  K.circle(
    K.width/2 + Math.cos(mainProgress * Math.PI * 4) * 100,
    K.height/2 + Math.sin(mainProgress * Math.PI * 4) * 100,
    20
  )

  // UI elements (medium, 5 seconds)
  K.Time.timeline("ui").use(K.time * 0.0004).for(5)
  const uiProgress = K.Time.progress()
  K.fillColor(`rgba(255, 255, 255, ${0.5 + Math.sin(uiProgress * Math.PI * 2) * 0.3})`)
  K.textAlign("center", "top")
  K.textSize(24)
  K.text(`Progress: ${Math.round(mainProgress * 100)}%`, K.width/2, 50)
}
```

### Complex Staggered Animation

```tsx
const draw = (K: KlintContext) => {
  K.background("#000")

  // Setup timeline
  K.Time.timeline("wave").use(K.time * 0.0008).for(4)

  // Grid of staggered elements
  const cols = 12
  const rows = 8
  K.Time.stagger(cols * rows, 0.05, (progress, id, total) => {
    const col = Math.floor(id * cols) % cols
    const row = Math.floor(id * cols / cols)

    const x = 50 + col * 50
    const y = 50 + row * 60

    // Apply easing
    const easedProgress = K.Easing.elasticOut(progress)

    // Size and color based on progress
    const size = 5 + easedProgress * 25
    const hue = (id * 15 + progress * 120) % 360

    K.fillColor(`hsl(${hue}, 80%, ${40 + progress * 40}%)`)
    K.circle(x, y, size)
  })
}
```

### Timeline Synchronization

```tsx
const draw = (K: KlintContext) => {
  // Initialize master timeline
  if (!K.State.has('masterTime')) {
    K.State.set('masterTime', 0)
  }

  // Update master time
  let masterTime = K.State.get('masterTime')
  masterTime += K.deltaTime * 0.001  // seconds
  K.State.set('masterTime', masterTime)

  K.background("#333")

  // Synchronized timelines
  K.Time.timeline("sync1").use(masterTime).for(3)
  K.Time.between(0, 1, (p) => {
    K.fillColor("red")
    K.circle(100, 200 + Math.sin(p * Math.PI * 2) * 50, 30)
  })

  K.Time.timeline("sync2").use(masterTime * 2).for(3)  // Double speed
  K.Time.between(0, 1, (p) => {
    K.fillColor("blue")
    K.circle(300, 200 + Math.sin(p * Math.PI * 2) * 50, 30)
  })

  K.Time.timeline("sync3").use(masterTime * 0.5).for(3)  // Half speed
  K.Time.between(0, 1, (p) => {
    K.fillColor("green")
    K.circle(500, 200 + Math.sin(p * Math.PI * 2) * 50, 30)
  })
}
```

## Best Practices

- **Use meaningful timeline names**: "intro", "main", "outro" instead of "t1", "t2"
- **Chain methods**: `K.Time.timeline("main").use(K.time * 0.001).for(5)`
- **Normalize durations**: Use seconds for time-based, frames for frame-based
- **Combine with Easing**: Apply easing functions to progress values for smoother animations
- **Use `between()` for sequences**: Clean way to create multi-phase animations
- **Leverage `stagger()`**: Perfect for grid animations, text reveals, particle systems

## Notes

- Default timeline duration is 480 frames (8 seconds at 60fps)
- Progress automatically wraps when duration > 0
- Each timeline maintains independent state
- `stagger()` creates delayed animations with configurable offset
- `between()` normalizes progress to 0-1 within the specified range
- Method chaining allows concise timeline setup
- Works seamlessly with `K.time`, `K.frame`, or custom progress sources

docs.4-elements/Vector:
# Vector

The Vector element provides 3D vector mathematics for position, velocity, and force calculations. While designed for 3D operations, it maintains backward compatibility with 2D use cases by defaulting the z-coordinate to 0.

## Creating Vectors

```tsx
const draw = (K: KlintContext) => {
  // Create a 2D vector (z defaults to 0)
  const position = K.createVector(100, 200);

  // Create a 3D vector explicitly
  const position3D = K.createVector(100, 200, 50);

  // Create from class (if needed)
  const velocity = new K.Vector(5, -3, 0);
}
```

## Properties

- `x`: X-coordinate
- `y`: Y-coordinate  
- `z`: Z-coordinate (defaults to 0 for 2D compatibility)

## Methods

### Basic Operations

#### add(vector)

```ts
add(v: Vector) => Vector
```

Adds another vector to this vector (including z component).

```tsx
const pos = K.createVector(100, 100, 10);
const vel = K.createVector(2, -1, 0.5);
pos.add(vel); // pos is now (102, 99, 10.5)
```

#### sub(vector)

```ts
sub(v: Vector) => Vector
```

Subtracts another vector from this vector (including z component).

```tsx
const a = K.createVector(100, 100, 20);
const b = K.createVector(20, 30, 5);
a.sub(b); // a is now (80, 70, 15)
```

#### mult(scalar)

```ts
mult(n: number) => Vector
```

Multiplies the vector by a scalar (affects all components).

```tsx
const vec = K.createVector(10, 20, 30);
vec.mult(0.5); // vec is now (5, 10, 15)
```

#### div(scalar)

```ts
div(n: number) => Vector
```

Divides the vector by a scalar (affects all components).

```tsx
const vec = K.createVector(100, 50, 25);
vec.div(10); // vec is now (10, 5, 2.5)
```

### Geometric Operations

#### rotate(angle)

```ts
rotate(angle: number) => Vector
```

Rotates the vector by an angle around the z-axis (2D rotation, z component unchanged).

```tsx
const vec = K.createVector(100, 0, 5);
vec.rotate(Math.PI / 2); // vec is now (0, 100, 5)
```

#### normalize()

```ts
normalize() => Vector
```

Normalizes the vector to unit length (magnitude = 1) in 3D space.

```tsx
const vec = K.createVector(100, 100, 100);
vec.normalize(); // vec is now (0.577..., 0.577..., 0.577...)
```

### Measurement Functions

#### mag() / length()

```ts
mag() => number
length() => number  // Alias for mag()
```

Returns the magnitude (length) of the vector in 3D space.

```tsx
const vec = K.createVector(2, 3, 6);
const magnitude = vec.mag(); // 7
```

#### dist(vector)

```ts
dist(v: Vector) => number
```

Calculates 3D distance to another vector.

```tsx
const a = K.createVector(0, 0, 0);
const b = K.createVector(2, 3, 6);
const distance = a.dist(b); // 7
```

#### dot(vector)

```ts
dot(v: Vector) => number
```

Calculates the 3D dot product with another vector.

```tsx
const a = K.createVector(2, 3, 4);
const b = K.createVector(5, 6, 7);
const dotProduct = a.dot(b); // 56 (2*5 + 3*6 + 4*7)
```

#### angle()

```ts
angle() => number
```

Returns the angle of the vector in radians (2D calculation, ignoring z).

```tsx
const vec = K.createVector(1, 1, 10);
const angle = vec.angle(); // π/4 radians (45 degrees)
```

### Advanced Operations

#### cross(vector)

```ts
cross(v: Vector) => Vector
```

Calculates the 3D cross product with another vector, returning a new vector.

```tsx
const a = K.createVector(1, 0, 0);
const b = K.createVector(0, 1, 0);
const cross = a.cross(b); // (0, 0, 1)
```

#### relativeTo(vector)

```ts
relativeTo(v: Vector) => Vector
```

Makes this vector relative to another vector by subtracting the reference vector.

```tsx
const worldPos = K.createVector(100, 200, 50);
const origin = K.createVector(50, 100, 25);
worldPos.relativeTo(origin); // worldPos is now (50, 100, 25)
```

#### lookAt(target)

```ts
lookAt(target: Vector) => Vector
```

Makes this vector point towards a target vector (normalized direction).

```tsx
const position = K.createVector(0, 0, 0);
const target = K.createVector(3, 4, 0);
position.lookAt(target); // position is now (0.6, 0.8, 0)
```

#### toScreen(width, height)

```ts
toScreen(width: number, height: number) => Vector
```

Converts from normalized coordinates (-1 to 1) to screen coordinates.

```tsx
const normalizedPos = K.createVector(0, 0, 0); // Center
normalizedPos.toScreen(800, 600); // (400, 300, 0)
```

#### slerp(vector, amount)

```ts
slerp(v: Vector, amt: number) => Vector
```

Spherical linear interpolation between this vector and another vector.

```tsx
const a = K.createVector(1, 0, 0);
const b = K.createVector(0, 1, 0);
a.slerp(b, 0.5); // Smooth interpolation halfway between vectors
```

### Utility Functions

#### copy()

```ts
copy() => Vector
```

Creates a copy of the vector (including z component).

```tsx
const original = K.createVector(10, 20, 30);
const copy = original.copy();
copy.mult(2); // original is unchanged
```

#### set(x, y, z)

```ts
set(x: number, y: number, z?: number) => Vector
```

Sets the vector's coordinates (z defaults to 0).

```tsx
const vec = K.createVector(0, 0, 0);
vec.set(100, 200, 300); // vec is now (100, 200, 300)
vec.set(50, 75); // vec is now (50, 75, 0)
```

### Static Methods

#### fromAngle(center, angle, radius)

```ts
Vector.fromAngle(center: Vector, angle: number, radius: number) => Vector
```

Creates a vector at a specific angle and distance from a center point (2D operation, preserves z).

```tsx
const center = K.createVector(200, 200, 100);
const point = K.Vector.fromAngle(center, Math.PI / 4, 100);
// point is 100 units away from center at 45 degrees, z=100
```

## Common Patterns

### 3D Physics Simulation

```tsx
const draw = (K: KlintContext) => {
  // Initialize if first frame
  if (!K.State.has('particles')) {
    const particles = [];
    for (let i = 0; i < 10; i++) {
      particles.push({
        position: K.createVector(K.width/2, K.height/2, 0),
        velocity: K.createVector(
          (Math.random() - 0.5) * 4,
          (Math.random() - 0.5) * 4,
          (Math.random() - 0.5) * 2
        ),
        acceleration: K.createVector(0, 0.1, 0) // gravity
      });
    }
    K.State.set('particles', particles);
  }

  const particles = K.State.get('particles');

  K.background("#222");

  particles.forEach(particle => {
    // Apply physics
    particle.velocity.add(particle.acceleration);
    particle.position.add(particle.velocity);

    // Bounce off edges (2D bounds)
    if (particle.position.x < 0 || particle.position.x > K.width) {
      particle.velocity.x *= -0.8;
    }
    if (particle.position.y < 0 || particle.position.y > K.height) {
      particle.velocity.y *= -0.8;
    }

    // Constrain to canvas
    particle.position.x = K.constrain(particle.position.x, 0, K.width);
    particle.position.y = K.constrain(particle.position.y, 0, K.height);

    // Size based on z-depth
    const size = 5 + particle.position.z * 0.1;

    // Draw particle
    K.fillColor("white");
    K.circle(particle.position.x, particle.position.y, size);
  });
}
```

### 3D Steering and Following

```tsx
const draw = (K: KlintContext) => {
  const { mouse } = KlintMouse();

  // Initialize agent
  if (!K.State.has('agent')) {
    K.State.set('agent', {
      position: K.createVector(K.width/2, K.height/2, 0),
      velocity: K.createVector(0, 0, 0),
      maxSpeed: 3
    });
  }

  const agent = K.State.get('agent');
  const target = K.createVector(mouse.x, mouse.y, 0);

  // Calculate desired velocity toward target
  const desired = target.copy().sub(agent.position);
  desired.normalize().mult(agent.maxSpeed);

  // Steering force
  const steer = desired.copy().sub(agent.velocity);
  steer.mult(0.1); // steering strength

  // Update agent
  agent.velocity.add(steer);
  agent.position.add(agent.velocity);

  K.background("#333");

  // Draw agent
  K.fillColor("cyan");
  K.circle(agent.position.x, agent.position.y, 20);

  // Draw 3D velocity vector
  K.strokeColor("yellow");
  K.strokeWidth(2);
  const velEnd = agent.position.copy().add(
    agent.velocity.copy().mult(10)
  );
  K.line(
    agent.position.x, agent.position.y,
    velEnd.x, velEnd.y
  );
}
```

### Spherical Interpolation Animation

```tsx
const draw = (K: KlintContext) => {
  if (!K.State.has('vectors')) {
    K.State.set('vectors', {
      start: K.createVector(1, 0, 0),
      end: K.createVector(0, 1, 0),
      current: K.createVector(1, 0, 0),
      t: 0
    });
  }

  const vectors = K.State.get('vectors');
  const center = K.createVector(K.width/2, K.height/2, 0);

  // Animate interpolation
  vectors.t += 0.01;
  if (vectors.t > 1) vectors.t = 0;

  // Reset current and interpolate
  vectors.current.set(vectors.start.x, vectors.start.y, vectors.start.z);
  vectors.current.slerp(vectors.end, vectors.t);

  K.background("#111");

  // Draw interpolated vector
  const scaled = vectors.current.copy().mult(100);
  const end = center.copy().add(scaled);

  K.strokeColor("white");
  K.strokeWidth(3);
  K.line(center.x, center.y, end.x, end.y);

  K.fillColor("red");
  K.circle(end.x, end.y, 8);
}
```

### Cross Product Visualization

```tsx
const draw = (K: KlintContext) => {
  const center = K.createVector(K.width/2, K.height/2, 0);

  // Two vectors
  const a = K.createVector(100, 0, 0);
  const b = K.createVector(50, 80, 0);

  // Cross product (perpendicular to both)
  const cross = a.cross(b);

  K.background("#222");

  // Draw vectors
  K.strokeColor("red");
  K.strokeWidth(3);
  K.line(center.x, center.y, center.x + a.x, center.y + a.y);

  K.strokeColor("blue"); 
  K.line(center.x, center.y, center.x + b.x, center.y + b.y);

  // Show cross product magnitude as text
  K.fillColor("white");
  K.text(`Cross product Z: ${cross.z.toFixed(2)}`, 10, 30);
}
```

## Notes

- **3D Support**: All operations now work in 3D space, with z defaulting to 0 for 2D compatibility
- **Method Chaining**: All vector operations modify the original vector and return `this` for chaining: `vec.normalize().mult(speed).add(offset)`
- **Copy When Needed**: Use `copy()` when you need to preserve the original vector during operations
- **Angles in Radians**: All angle operations use radians; use `degrees * (Math.PI / 180)` for conversion
- **Performance**: For performance-critical code, consider reusing vectors instead of creating new ones
- **Cross Product**: Returns a new vector perpendicular to both input vectors (right-hand rule)
- **Slerp**: Provides smooth interpolation that maintains constant angular velocity
- **Screen Coordinates**: `toScreen()` converts from normalized device coordinates to pixel coordinates

